function NewChapterUtils.CalcOutPos2D(enterId, camera)
    if isNull(camera) then
        return -1
    end
    if enterId == NewChapterConstants.CharacterEnterType.None then
        return -1
    end
    if not camera.orthographic then
        return -1
    end
    local camBorder = CSGameUtils.CalculateCameraViewSize(camera)
    camBorder = camBorder.x / 2
    local halfText = NewChapterConstants.TextureParams.Height / 2 / NewChapterConstants.TextureParams.Pixel
    camBorder = camBorder + halfText
    if enterId == NewChapterConstants.CharacterEnterType.LeftIn or enterId == NewChapterConstants.CharacterEnterType.LeftOut then
        return Vector3.New(-camBorder, -camera.orthographicSize, NewChapterConstants.TextureParams.Depth)
    else
        return Vector3.New(camBorder, -camera.orthographicSize, NewChapterConstants.TextureParams.Depth)
    end
end

function NewChapterUtils.CalcOutPos3D(enterId, node, camera)
    if isNull(camera) then
        return -1
    end
    if enterId == NewChapterConstants.CharacterEnterType.None then
        return -1
    end
    if camera.orthographic then
        return -1
    end
    --Vector3.Distance(node.position, camera.position)
    local depth = camera.transform.position.z - node.position.z
    local camBorder = CSGameUtils.CalculateCameraViewSize(camera, depth)
    camBorder = camBorder.x / 2
    local halfText = 0.8
    camBorder = camBorder + halfText
    --3DCamera 180的旋转
    if enterId == NewChapterConstants.CharacterEnterType.LeftIn or enterId == NewChapterConstants.CharacterEnterType.LeftOut then
        return Vector3.New(camBorder, node.localPosition.y, node.localPosition.z)
    else
        return Vector3.New(-camBorder, node.localPosition.y, node.localPosition.z)
    end
end

function NewChapterUtils.IsCloseDis(posId)
    return posId >= NewChapterConstants.CharacterPos.CloseDisLeft1 and posId <= NewChapterConstants.CharacterPos.CloseDisRight2
end

function NewChapterUtils.GetDisType(posId)
    if posId >= NewChapterConstants.CharacterPos.CloseDisLeft1 and posId <= NewChapterConstants.CharacterPos.CloseDisRight1 then
        return NewChapterConstants.DisType.CloseDis
    elseif posId >= NewChapterConstants.CharacterPos.MidDisLeft1 and posId <= NewChapterConstants.CharacterPos.MidDisRight1 then
        return NewChapterConstants.DisType.MidDis
    elseif posId >= NewChapterConstants.CharacterPos.MixA1 and posId <= NewChapterConstants.CharacterPos.MixC9 then
        return NewChapterConstants.DisType.MixDis
    elseif posId >= NewChapterConstants.CharacterPos.OP01 and posId <= NewChapterConstants.CharacterPos.OP03 then
        return NewChapterConstants.DisType.MixDis
    elseif posId == NewChapterConstants.CharacterPos.Hand1 then
        return NewChapterConstants.DisType.MixDis
    elseif posId == NewChapterConstants.CharacterPos.Hand2 then
        return NewChapterConstants.DisType.MixDis
    end
end


function NewChapterUtils.GetEnterPos2D(posId, enterId, camera, trans)
    local outNode = NewChapterUtils.CalcOutPos2D(enterId, camera)
    local nodeName = NewChapterUtils.GetObjectNode(posId)
    local node = trans:Find(nodeName)
    if enterId == NewChapterConstants.CharacterEnterType.LeftOut or enterId == NewChapterConstants.CharacterEnterType.RightOut then
        return { node.localPosition, outNode }
    elseif enterId == NewChapterConstants.CharacterEnterType.None then
        return { node.localPosition }
    else
        return { outNode, node.localPosition }
    end
end

function NewChapterUtils.GetEnterPos3D(posId, enterId, camera, trans)
    local nodeName = NewChapterUtils.GetObjectNode(posId)
    local node = trans:Find(nodeName)
    local outNode = NewChapterUtils.CalcOutPos3D(enterId, node, camera)
    if enterId == NewChapterConstants.CharacterEnterType.LeftOut or enterId == NewChapterConstants.CharacterEnterType.RightOut then
        return { node.localPosition, outNode }
    elseif enterId == NewChapterConstants.CharacterEnterType.None then
        return { node.localPosition }
    else
        return { outNode, node.localPosition }
    end
end

function NewChapterUtils.Get2DCameraSize(isMid)
    if isMid then
        return 5.4, 0
    else
        return 3.6, 1.8
    end
end

function NewChapterUtils.GetCharacterRotation(rotation)
    if rotation == NewChapterConstants.CharacterRotation.Forward then
        return Unity_Quaternion.Euler(0,0,0)
    elseif rotation == NewChapterConstants.CharacterRotation.QuarterLeft then
        return Unity_Quaternion.Euler(0,30,0)
    elseif rotation == NewChapterConstants.CharacterRotation.QuarterRight then
        return Unity_Quaternion.Euler(0,-30,0)
    elseif rotation == NewChapterConstants.CharacterRotation.HalfLeft then
        return Unity_Quaternion.Euler(0,90,0)
    elseif rotation == NewChapterConstants.CharacterRotation.HalfRight then
        return Unity_Quaternion.Euler(0,-90,0)
    elseif rotation == NewChapterConstants.CharacterRotation.Back then
        return Unity_Quaternion.Euler(0,180,0)
    elseif rotation == NewChapterConstants.CharacterRotation.BackLeft then
        return Unity_Quaternion.Euler(0,135,0)
    elseif rotation == NewChapterConstants.CharacterRotation.BackRight then
        return Unity_Quaternion.Euler(0,-135,0)

    end
end


function NewChapterUtils.CalcMoveTime(startPos, destPos, camera)

    local depth = camera.transform.position.z - destPos.z
    local dis = math.abs(startPos.x - destPos.x)
    local camBorder = CSGameUtils.CalculateCameraViewSize(camera, depth)
    camBorder = camBorder.x / 2
    --1920/100/2 半屏
    if dis > camBorder then
        return NewChapterConstants.CharacterEnterParam.LongTime
    else
        return NewChapterConstants.CharacterEnterParam.ShortTime
    end
end

function NewChapterUtils.GetModelVolume(model)
    local collider = model.gameObject:GetComponent(typeof(BoxCollider))
    local t = {}
    t.center = collider.center
    t.size = collider.size
    return t
end

function NewChapterUtils.SetMatVectorArg(model, propName, propValue)
    local skin = model.gameObject:GetComponent(typeof(CS.UnityEngine.MeshRenderer))
    local block = CS.UnityEngine.MaterialPropertyBlock()
    local vector4 = CS.UnityEngine.Vector4(propValue.x, propValue.y, propValue.z, 0)
    skin:GetPropertyBlock(block)
    block:SetVector(propName, vector4)
    skin:SetPropertyBlock(block)
end

function NewChapterUtils.CloseFaceForward(model)
    local face = model.transform:Find("Unity_Export_Grp/Geometry/face")
    if isNull(face) then
        return
    end
    face = face.gameObject:GetComponent(typeof(FaceForward))
    if isNull(face) then
        return
    end
    face.enabled = false
end


