function NewChapterUtils.NeedModify(str)
    local need = true
    for i, v in pairs(NewChapterConstants.ModelBsSuffix) do
        if string.endsWith(str, v) then
            need = false
            break
        end
    end
    
    return need
end

function NewChapterUtils.FakeOffsetVo()
    local tt = import("Game.Setting.Vo.NewChapterPosVo")
    local vo = tt.New()
    vo:FakeVo()
    return vo
end

---@param vo NewChapter2DVo
function NewChapterUtils.HasOption(vo)
    if vo == nil then
        return false
    end
    
    return vo.type == NewChapterConstants.NewType.ChapterOption or vo.type == NewChapterConstants.NewType.RecordChapterOption
end

return NewChapterUtils
